package com.casecraft.model;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="clues") public class Clue { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="case_id",nullable=false) private CaseFile caseFile; @Column(nullable=false) private String title; @Column(length=2000) private String detail; private String importance="MEDIUM"; private double x=50,y=50; @OneToMany(mappedBy="source",cascade=CascadeType.ALL,orphanRemoval=true) private java.util.List<ClueConnection> outgoing=new java.util.ArrayList<>(); @OneToMany(mappedBy="target",cascade=CascadeType.ALL,orphanRemoval=true) private java.util.List<ClueConnection> incoming=new java.util.ArrayList<>(); public UUID getId(){return id;} public CaseFile getCaseFile(){return caseFile;} public void setCaseFile(CaseFile c){caseFile=c;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getDetail(){return detail;} public void setDetail(String v){detail=v;} public String getImportance(){return importance;} public void setImportance(String v){importance=v;} public double getX(){return x;} public void setX(double v){x=v;} public double getY(){return y;} public void setY(double v){y=v;} }
